export const DUAS_LIST: Dua[] = [
  // ── Matin & soir ────────────────────────────────────────────
  { id: 'sabah', cat: 'matin-soir', title: 'Par Toi nous atteignons le matin', when: 'Le matin (variante du soir indiquée)', ar: 'اللَّهُمَّ بِكَ أَصْبَحْنَا، وَبِكَ أَمْسَيْنَا، وَبِكَ نَحْيَا، وَبِكَ نَمُوتُ، وَإِلَيْكَ النُّشُورُ', tr: 'Allāhumma bika aṣbaḥnā, wa bika amsaynā, wa bika naḥyā, wa bika namūtu, wa ilayka-n-nushūr', fr: 'Ô Allah, c’est par Toi que nous atteignons le matin et le soir, par Toi que nous vivons et mourons, et vers Toi est la résurrection.', note: 'Le soir : « Allāhumma bika amsaynā, wa bika aṣbaḥnā, wa bika naḥyā, wa bika namūtu, wa ilayka-l-maṣīr » — et vers Toi est le retour.', ref: 'Jami‘ at-Tirmidhi 3391 ; Sunan Abi Dawud 5068' },
  { id: 'amsayna', cat: 'matin-soir', title: 'Nous voici au soir, et la royauté est à Allah', when: 'Le soir (le matin : « aṣbaḥnā… hādha-l-yawm »)', ar: 'أَمْسَيْنَا وَأَمْسَى الْمُلْكُ لِلَّهِ، وَالْحَمْدُ لِلَّهِ، لَا إِلَهَ إِلَّا اللَّهُ وَحْدَهُ لَا شَرِيكَ لَهُ، لَهُ الْمُلْكُ وَلَهُ الْحَمْدُ وَهُوَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ، اللَّهُمَّ أَسْأَلُكَ خَيْرَ هَذِهِ اللَّيْلَةِ، وَأَعُوذُ بِكَ مِنْ شَرِّ هَذِهِ اللَّيْلَةِ وَشَرِّ مَا بَعْدَهَا، اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنَ الْكَسَلِ وَسُوءِ الْكِبَرِ، اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنْ عَذَابٍ فِي النَّارِ وَعَذَابٍ فِي الْقَبْرِ', tr: 'Amsaynā wa amsa-l-mulku li-llāh, wa-l-ḥamdu li-llāh, lā ilāha illa-llāhu waḥdahu lā sharīka lah, lahu-l-mulku wa lahu-l-ḥamdu wa huwa ‘alā kulli shay’in qadīr. Allāhumma as’aluka khayra hādhihi-l-layla, wa a‘ūdhu bika min sharri hādhihi-l-layla wa sharri mā ba‘dahā. Allāhumma innī a‘ūdhu bika mina-l-kasali wa sū’i-l-kibar. Allāhumma innī a‘ūdhu bika min ‘adhābin fi-n-nāri wa ‘adhābin fi-l-qabr', fr: 'Nous voici au soir et la royauté appartient à Allah ; louange à Allah. Il n’y a de divinité qu’Allah, Seul, sans associé ; à Lui la royauté et la louange, et Il est capable de toute chose. Ô Allah, je Te demande le bien de cette nuit et je cherche refuge auprès de Toi contre le mal de cette nuit et de ce qui la suit. Ô Allah, je cherche refuge auprès de Toi contre la paresse et les maux de la vieillesse ; je cherche refuge auprès de Toi contre un châtiment dans le Feu et un châtiment dans la tombe.', ref: 'Sahih Muslim 2723' },
  { id: 'bismillah-ladhi', cat: 'matin-soir', title: 'Au nom d’Allah, avec le nom duquel rien ne nuit', when: 'Matin et soir', reps: 3, ar: 'بِسْمِ اللَّهِ الَّذِي لَا يَضُرُّ مَعَ اسْمِهِ شَيْءٌ فِي الْأَرْضِ وَلَا فِي السَّمَاءِ، وَهُوَ السَّمِيعُ الْعَلِيمُ', tr: 'Bismi-llāhi-lladhī lā yaḍurru ma‘a-smihi shay’un fi-l-arḍi wa lā fi-s-samā’, wa huwa-s-samī‘u-l-‘alīm', fr: 'Au nom d’Allah, avec le nom duquel rien ne peut nuire sur terre ni dans le ciel ; Il est Celui qui entend tout, l’Omniscient.', ref: 'Sunan Abi Dawud 5088 ; Jami‘ at-Tirmidhi 3388' },
  { id: 'afini', cat: 'matin-soir', title: 'Préserve-moi dans mon corps', when: 'Matin et soir', reps: 3, ar: 'اللَّهُمَّ عَافِنِي فِي بَدَنِي، اللَّهُمَّ عَافِنِي فِي سَمْعِي، اللَّهُمَّ عَافِنِي فِي بَصَرِي، لَا إِلَهَ إِلَّا أَنْتَ', tr: 'Allāhumma ‘āfinī fī badanī, Allāhumma ‘āfinī fī sam‘ī, Allāhumma ‘āfinī fī baṣarī, lā ilāha illā ant', fr: 'Ô Allah, préserve-moi dans mon corps ; ô Allah, préserve-moi dans mon ouïe ; ô Allah, préserve-moi dans ma vue. Il n’y a de divinité que Toi.', ref: 'Sunan Abi Dawud 5090' },
  { id: 'kufr-faqr', cat: 'matin-soir', title: 'Refuge contre la mécréance et la pauvreté', when: 'Matin et soir', reps: 3, ar: 'اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنَ الْكُفْرِ وَالْفَقْرِ، اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنْ عَذَابِ الْقَبْرِ، لَا إِلَهَ إِلَّا أَنْتَ', tr: 'Allāhumma innī a‘ūdhu bika mina-l-kufri wa-l-faqr, Allāhumma innī a‘ūdhu bika min ‘adhābi-l-qabr, lā ilāha illā ant', fr: 'Ô Allah, je cherche refuge auprès de Toi contre la mécréance et la pauvreté ; ô Allah, je cherche refuge auprès de Toi contre le châtiment de la tombe. Il n’y a de divinité que Toi.', ref: 'Sunan Abi Dawud 5090' },
  { id: 'afiya', cat: 'matin-soir', title: 'Demande de préservation (al-‘āfiya)', when: 'Matin et soir', ar: 'اللَّهُمَّ إِنِّي أَسْأَلُكَ الْعَافِيَةَ فِي الدُّنْيَا وَالْآخِرَةِ، اللَّهُمَّ إِنِّي أَسْأَلُكَ الْعَفْوَ وَالْعَافِيَةَ فِي دِينِي وَدُنْيَايَ وَأَهْلِي وَمَالِي، اللَّهُمَّ اسْتُرْ عَوْرَاتِي، وَآمِنْ رَوْعَاتِي، اللَّهُمَّ احْفَظْنِي مِنْ بَيْنِ يَدَيَّ وَمِنْ خَلْفِي، وَعَنْ يَمِينِي وَعَنْ شِمَالِي، وَمِنْ فَوْقِي، وَأَعُوذُ بِعَظَمَتِكَ أَنْ أُغْتَالَ مِنْ تَحْتِي', tr: 'Allāhumma innī as’aluka-l-‘āfiyata fi-d-dunyā wa-l-ākhira. Allāhumma innī as’aluka-l-‘afwa wa-l-‘āfiyata fī dīnī wa dunyāya wa ahlī wa mālī. Allāhumma-stur ‘awrātī wa āmin raw‘ātī. Allāhumma-ḥfaẓnī min bayni yadayya wa min khalfī, wa ‘an yamīnī wa ‘an shimālī, wa min fawqī, wa a‘ūdhu bi-‘aẓamatika an ughtāla min taḥtī', fr: 'Ô Allah, je Te demande la préservation ici-bas et dans l’au-delà. Ô Allah, je Te demande le pardon et la préservation dans ma religion, ma vie, ma famille et mes biens. Ô Allah, couvre mes failles et apaise mes frayeurs. Ô Allah, protège-moi devant et derrière moi, à ma droite et à ma gauche, et au-dessus de moi ; je cherche refuge en Ta grandeur contre le fait d’être pris par traîtrise par-dessous.', ref: 'Sunan Abi Dawud 5074 ; Sunan Ibn Majah 3871' },
  { id: 'fatir', cat: 'matin-soir', title: 'Ô Créateur des cieux et de la terre', when: 'Matin, soir et au coucher', ar: 'اللَّهُمَّ فَاطِرَ السَّمَاوَاتِ وَالْأَرْضِ، عَالِمَ الْغَيْبِ وَالشَّهَادَةِ، رَبَّ كُلِّ شَيْءٍ وَمَلِيكَهُ، أَشْهَدُ أَنْ لَا إِلَهَ إِلَّا أَنْتَ، أَعُوذُ بِكَ مِنْ شَرِّ نَفْسِي، وَشَرِّ الشَّيْطَانِ وَشِرْكِهِ', tr: 'Allāhumma fāṭira-s-samāwāti wa-l-arḍ, ‘ālima-l-ghaybi wa-sh-shahāda, rabba kulli shay’in wa malīkah, ashhadu an lā ilāha illā ant, a‘ūdhu bika min sharri nafsī wa sharri-sh-shayṭāni wa shirkih', fr: 'Ô Allah, Créateur des cieux et de la terre, Connaisseur de l’invisible et du visible, Seigneur et Souverain de toute chose : j’atteste qu’il n’y a de divinité que Toi. Je cherche refuge auprès de Toi contre le mal de mon âme, et contre le mal de Satan et de son associationnisme.', ref: 'Sunan Abi Dawud 5067 ; Jami‘ at-Tirmidhi 3392' },
  { id: 'subhan-bihamdih', cat: 'matin-soir', title: 'Gloire et louange à Allah', when: 'Matin et soir', reps: 100, ar: 'سُبْحَانَ اللَّهِ وَبِحَمْدِهِ', tr: 'Subḥāna-llāhi wa bi-ḥamdih', fr: 'Gloire et louange à Allah.', ref: 'Sahih Muslim 2692 ; Sahih al-Bukhari 6405' },
  { id: 'tahlil', cat: 'matin-soir', title: 'Le tahlil complet', when: 'Chaque jour', reps: 100, ar: 'لَا إِلَهَ إِلَّا اللَّهُ وَحْدَهُ لَا شَرِيكَ لَهُ، لَهُ الْمُلْكُ وَلَهُ الْحَمْدُ، وَهُوَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ', tr: 'Lā ilāha illa-llāhu waḥdahu lā sharīka lah, lahu-l-mulku wa lahu-l-ḥamd, wa huwa ‘alā kulli shay’in qadīr', fr: 'Il n’y a de divinité qu’Allah, Seul, sans associé ; à Lui la royauté et la louange, et Il est capable de toute chose.', ref: 'Sahih al-Bukhari 3293' },

  // ── Sommeil & réveil ────────────────────────────────────────
  { id: 'nawm', cat: 'sommeil', title: 'En Ton nom je meurs et je vis', when: 'Au coucher / au réveil', ar: 'بِاسْمِكَ اللَّهُمَّ أَمُوتُ وَأَحْيَا — الْحَمْدُ لِلَّهِ الَّذِي أَحْيَانَا بَعْدَ مَا أَمَاتَنَا وَإِلَيْهِ النُّشُورُ', tr: 'Bismika-llāhumma amūtu wa aḥyā — Al-ḥamdu li-llāhi-lladhī aḥyānā ba‘da mā amātanā wa ilayhi-n-nushūr', fr: 'En Ton nom, ô Allah, je meurs et je vis. — (Au réveil) Louange à Allah qui nous a redonné la vie après nous avoir fait mourir, et vers Lui est la résurrection.', ref: 'Sahih al-Bukhari 6324 ; Sahih al-Bukhari 6312' },
  { id: 'aslamtu', cat: 'sommeil', title: 'Je me soumets à Toi', when: 'En se couchant sur le côté droit, en dernier', ar: 'اللَّهُمَّ أَسْلَمْتُ وَجْهِي إِلَيْكَ، وَفَوَّضْتُ أَمْرِي إِلَيْكَ، وَأَلْجَأْتُ ظَهْرِي إِلَيْكَ، رَغْبَةً وَرَهْبَةً إِلَيْكَ، لَا مَلْجَأَ وَلَا مَنْجَا مِنْكَ إِلَّا إِلَيْكَ، اللَّهُمَّ آمَنْتُ بِكِتَابِكَ الَّذِي أَنْزَلْتَ، وَبِنَبِيِّكَ الَّذِي أَرْسَلْتَ', tr: 'Allāhumma aslamtu wajhī ilayk, wa fawwaḍtu amrī ilayk, wa alja’tu ẓahrī ilayk, raghbatan wa rahbatan ilayk, lā malja’a wa lā manjā minka illā ilayk. Allāhumma āmantu bi-kitābika-lladhī anzalt, wa bi-nabiyyika-lladhī arsalt', fr: 'Ô Allah, je T’ai soumis mon visage, je T’ai confié mon affaire, je me suis adossé à Toi, par désir et par crainte de Toi. Il n’y a ni refuge ni salut contre Toi si ce n’est auprès de Toi. Ô Allah, j’ai cru en Ton Livre que Tu as révélé et en Ton Prophète que Tu as envoyé.', ref: 'Sahih al-Bukhari 247' },
  { id: 'bismika-rabbi', cat: 'sommeil', title: 'En Ton nom, Seigneur, je pose mon côté', when: 'Au coucher', ar: 'بِاسْمِكَ رَبِّ وَضَعْتُ جَنْبِي، وَبِكَ أَرْفَعُهُ، إِنْ أَمْسَكْتَ نَفْسِي فَارْحَمْهَا، وَإِنْ أَرْسَلْتَهَا فَاحْفَظْهَا بِمَا تَحْفَظُ بِهِ عِبَادَكَ الصَّالِحِينَ', tr: 'Bismika rabbi waḍa‘tu janbī, wa bika arfa‘uh, in amsakta nafsī farḥamhā, wa in arsaltahā faḥfaẓhā bimā taḥfaẓu bihi ‘ibādaka-ṣ-ṣāliḥīn', fr: 'En Ton nom, Seigneur, je pose mon côté et par Toi je le relève. Si Tu retiens mon âme, fais-lui miséricorde ; si Tu la renvoies, protège-la comme Tu protèges Tes serviteurs vertueux.', ref: 'Sahih al-Bukhari 6320' },
  { id: 'qini', cat: 'sommeil', title: 'Préserve-moi de Ton châtiment', when: 'Main droite sous la joue, au coucher', reps: 3, ar: 'اللَّهُمَّ قِنِي عَذَابَكَ يَوْمَ تَبْعَثُ عِبَادَكَ', tr: 'Allāhumma qinī ‘adhābaka yawma tab‘athu ‘ibādak', fr: 'Ô Allah, préserve-moi de Ton châtiment le jour où Tu ressusciteras Tes serviteurs.', ref: 'Sunan Abi Dawud 5045' },
  { id: 'atamana', cat: 'sommeil', title: 'Louange à Celui qui nous a nourris et abrités', when: 'Au coucher', ar: 'الْحَمْدُ لِلَّهِ الَّذِي أَطْعَمَنَا وَسَقَانَا، وَكَفَانَا وَآوَانَا، فَكَمْ مِمَّنْ لَا كَافِيَ لَهُ وَلَا مُؤْوِيَ', tr: 'Al-ḥamdu li-llāhi-lladhī aṭ‘amanā wa saqānā, wa kafānā wa āwānā, fa-kam mimman lā kāfiya lahu wa lā mu’wī', fr: 'Louange à Allah qui nous a nourris et désaltérés, qui nous a suffi et abrités ; combien n’ont personne pour leur suffire ni pour les abriter !', ref: 'Sahih Muslim 2715' },
  { id: 'tasbih-fatima', cat: 'sommeil', title: 'Le tasbih de Fatima', when: 'Au coucher', reps: 34, ar: 'سُبْحَانَ اللَّهِ (٣٣) — الْحَمْدُ لِلَّهِ (٣٣) — اللَّهُ أَكْبَرُ (٣٤)', tr: 'Subḥāna-llāh (33) — Al-ḥamdu li-llāh (33) — Allāhu akbar (34)', fr: 'Gloire à Allah (33 fois), louange à Allah (33 fois), Allah est le plus grand (34 fois). Le Prophète ﷺ l’a enseigné à ‘Ali et Fatima comme « meilleur qu’un serviteur ».', ref: 'Sahih al-Bukhari 6318' },
  { id: 'muawwidhat-nawm', cat: 'sommeil', title: 'Les trois Qul soufflées dans les mains', when: 'Au coucher', reps: 3, ar: 'قُلْ هُوَ اللَّهُ أَحَدٌ… — قُلْ أَعُوذُ بِرَبِّ الْفَلَقِ… — قُلْ أَعُوذُ بِرَبِّ النَّاسِ…', tr: 'Qul huwa-llāhu aḥad… — Qul a‘ūdhu bi-rabbi-l-falaq… — Qul a‘ūdhu bi-rabbi-n-nās…', fr: 'Joindre les mains, y souffler en récitant les sourates al-Ikhlas, al-Falaq et an-Nas, puis les passer sur le corps en commençant par la tête et le visage. Le faire trois fois.', ref: 'Sahih al-Bukhari 5017 ; Coran 112–114' },
  { id: 'kursi', cat: 'sommeil', title: 'Ayat al-Kursi', when: 'Au coucher (aussi après la prière)', ar: 'اللَّهُ لَا إِلَهَ إِلَّا هُوَ الْحَيُّ الْقَيُّومُ، لَا تَأْخُذُهُ سِنَةٌ وَلَا نَوْمٌ، لَهُ مَا فِي السَّمَاوَاتِ وَمَا فِي الْأَرْضِ، مَنْ ذَا الَّذِي يَشْفَعُ عِنْدَهُ إِلَّا بِإِذْنِهِ، يَعْلَمُ مَا بَيْنَ أَيْدِيهِمْ وَمَا خَلْفَهُمْ، وَلَا يُحِيطُونَ بِشَيْءٍ مِنْ عِلْمِهِ إِلَّا بِمَا شَاءَ، وَسِعَ كُرْسِيُّهُ السَّمَاوَاتِ وَالْأَرْضَ، وَلَا يَئُودُهُ حِفْظُهُمَا، وَهُوَ الْعَلِيُّ الْعَظِيمُ', tr: 'Allāhu lā ilāha illā huwa-l-ḥayyu-l-qayyūm, lā ta’khudhuhu sinatun wa lā nawm, lahu mā fi-s-samāwāti wa mā fi-l-arḍ, man dha-lladhī yashfa‘u ‘indahu illā bi-idhnih, ya‘lamu mā bayna aydīhim wa mā khalfahum, wa lā yuḥīṭūna bi-shay’in min ‘ilmihi illā bimā shā’, wasi‘a kursiyyuhu-s-samāwāti wa-l-arḍ, wa lā ya’ūduhu ḥifẓuhumā, wa huwa-l-‘aliyyu-l-‘aẓīm', fr: 'Allah ! Point de divinité à part Lui, le Vivant, Celui qui subsiste par Lui-même. Ni somnolence ni sommeil ne Le saisissent. À Lui appartient ce qui est dans les cieux et sur la terre. Qui peut intercéder auprès de Lui sans Sa permission ? Il connaît ce qui est devant eux et derrière eux, et ils n’embrassent de Sa science que ce qu’Il veut. Son Trône déborde les cieux et la terre, dont la garde ne Lui coûte aucune peine. Et Il est le Très-Haut, l’Immense.', ref: 'Coran 2:255 ; Sahih al-Bukhari 2311' },
  { id: 'taarra', cat: 'sommeil', title: 'En se réveillant la nuit', when: 'Réveil pendant la nuit', ar: 'لَا إِلَهَ إِلَّا اللَّهُ وَحْدَهُ لَا شَرِيكَ لَهُ، لَهُ الْمُلْكُ وَلَهُ الْحَمْدُ، وَهُوَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ، الْحَمْدُ لِلَّهِ، وَسُبْحَانَ اللَّهِ، وَلَا إِلَهَ إِلَّا اللَّهُ، وَاللَّهُ أَكْبَرُ، وَلَا حَوْلَ وَلَا قُوَّةَ إِلَّا بِاللَّهِ، اللَّهُمَّ اغْفِرْ لِي', tr: 'Lā ilāha illa-llāhu waḥdahu lā sharīka lah, lahu-l-mulku wa lahu-l-ḥamd, wa huwa ‘alā kulli shay’in qadīr. Al-ḥamdu li-llāh, wa subḥāna-llāh, wa lā ilāha illa-llāh, wa-llāhu akbar, wa lā ḥawla wa lā quwwata illā bi-llāh. Allāhumma-ghfir lī', fr: 'Il n’y a de divinité qu’Allah, Seul, sans associé… Louange à Allah, gloire à Allah, il n’y a de divinité qu’Allah, Allah est le plus grand, il n’y a de force ni de puissance qu’en Allah. Ô Allah, pardonne-moi. (Celui qui dit cela puis invoque est exaucé.)', ref: 'Sahih al-Bukhari 1154' },

  // ── Repas ───────────────────────────────────────────────────
  { id: 'akl', cat: 'repas', title: 'Avant de manger', when: 'Avant de manger (en cas d’oubli)', ar: 'بِسْمِ اللَّهِ — بِسْمِ اللَّهِ أَوَّلَهُ وَآخِرَهُ', tr: 'Bismi-llāh — Bismi-llāhi awwalahu wa ākhirah', fr: 'On dit « Bismillah » avant de manger ; si on l’a oublié : « Au nom d’Allah, au début et à la fin ».', ref: 'Sunan Abi Dawud 3767 ; Jami‘ at-Tirmidhi 1858 ; Sahih al-Bukhari 5376' },
  { id: 'ba3d', cat: 'repas', title: 'Après le repas', when: 'Après le repas', ar: 'الْحَمْدُ لِلَّهِ الَّذِي أَطْعَمَنِي هَذَا الطَّعَامَ، وَرَزَقَنِيهِ مِنْ غَيْرِ حَوْلٍ مِنِّي وَلَا قُوَّةٍ', tr: 'Al-ḥamdu li-llāhi-lladhī aṭ‘amanī hādha-ṭ-ṭa‘ām, wa razaqanīhi min ghayri ḥawlin minnī wa lā quwwah', fr: 'Louange à Allah qui m’a nourri de ce repas et me l’a accordé sans force ni puissance de ma part.', ref: 'Sunan Abi Dawud 4023 ; Jami‘ at-Tirmidhi 3458' },
  { id: 'kathiran', cat: 'repas', title: 'Louange abondante après le repas', when: 'En levant la nappe', ar: 'الْحَمْدُ لِلَّهِ كَثِيرًا طَيِّبًا مُبَارَكًا فِيهِ، غَيْرَ مَكْفِيٍّ، وَلَا مُوَدَّعٍ، وَلَا مُسْتَغْنًى عَنْهُ رَبَّنَا', tr: 'Al-ḥamdu li-llāhi kathīran ṭayyiban mubārakan fīh, ghayra makfiyyin wa lā muwadda‘in wa lā mustaghnan ‘anhu rabbanā', fr: 'Louange à Allah, abondante, pure et bénie ; une louange qui ne suffit jamais, que l’on ne délaisse pas et dont on ne peut se passer, ô notre Seigneur.', ref: 'Sahih al-Bukhari 5458' },
  { id: 'hote', cat: 'repas', title: 'Pour celui qui vous a reçu', when: 'Après avoir été invité', ar: 'اللَّهُمَّ بَارِكْ لَهُمْ فِيمَا رَزَقْتَهُمْ، وَاغْفِرْ لَهُمْ وَارْحَمْهُمْ', tr: 'Allāhumma bārik lahum fīmā razaqtahum, wa-ghfir lahum wa-rḥamhum', fr: 'Ô Allah, bénis-les dans ce que Tu leur as accordé, pardonne-leur et fais-leur miséricorde.', ref: 'Sahih Muslim 2042' },

  // ── Maison & quotidien ──────────────────────────────────────
  { id: 'khuruj', cat: 'maison', title: 'En sortant de chez soi', when: 'En sortant de chez soi', ar: 'بِسْمِ اللَّهِ، تَوَكَّلْتُ عَلَى اللَّهِ، وَلَا حَوْلَ وَلَا قُوَّةَ إِلَّا بِاللَّهِ', tr: 'Bismi-llāh, tawakkaltu ‘ala-llāh, wa lā ḥawla wa lā quwwata illā bi-llāh', fr: 'Au nom d’Allah, je m’en remets à Allah ; il n’y a de force ni de puissance qu’en Allah.', ref: 'Sunan Abi Dawud 5095 ; Jami‘ at-Tirmidhi 3426' },
  { id: 'dalal', cat: 'maison', title: 'Refuge contre l’égarement', when: 'En sortant de chez soi', ar: 'اللَّهُمَّ إِنِّي أَعُوذُ بِكَ أَنْ أَضِلَّ أَوْ أُضَلَّ، أَوْ أَزِلَّ أَوْ أُزَلَّ، أَوْ أَظْلِمَ أَوْ أُظْلَمَ، أَوْ أَجْهَلَ أَوْ يُجْهَلَ عَلَيَّ', tr: 'Allāhumma innī a‘ūdhu bika an aḍilla aw uḍall, aw azilla aw uzall, aw aẓlima aw uẓlam, aw ajhala aw yujhala ‘alayy', fr: 'Ô Allah, je cherche refuge auprès de Toi contre le fait de m’égarer ou d’être égaré, de faillir ou d’être fait faillir, d’être injuste ou de subir l’injustice, d’agir sottement ou de subir la sottise d’autrui.', ref: 'Sunan Abi Dawud 5094' },
  { id: 'dukhul', cat: 'maison', title: 'En entrant chez soi', when: 'En entrant chez soi et au repas', ar: 'بِسْمِ اللَّهِ', tr: 'Bismi-llāh', fr: 'Mentionner le nom d’Allah en entrant chez soi et au moment du repas : Satan dit alors à ses compagnons « Ni gîte ni dîner pour vous ici ».', ref: 'Sahih Muslim 2018' },
  { id: 'khala', cat: 'maison', title: 'En entrant aux toilettes', when: 'Avant d’entrer aux toilettes', ar: 'اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنَ الْخُبُثِ وَالْخَبَائِثِ', tr: 'Allāhumma innī a‘ūdhu bika mina-l-khubuthi wa-l-khabā’ith', fr: 'Ô Allah, je cherche refuge auprès de Toi contre les démons mâles et femelles (contre le mal et ceux qui le portent).', ref: 'Sahih al-Bukhari 142' },
  { id: 'ghufranak', cat: 'maison', title: 'En sortant des toilettes', when: 'En sortant des toilettes', ar: 'غُفْرَانَكَ', tr: 'Ghufrānak', fr: '(Je Te demande) Ton pardon.', ref: 'Sunan Abi Dawud 30' },
  { id: 'wudu', cat: 'maison', title: 'Après les ablutions', when: 'Après les ablutions', ar: 'أَشْهَدُ أَنْ لَا إِلَهَ إِلَّا اللَّهُ وَحْدَهُ لَا شَرِيكَ لَهُ، وَأَشْهَدُ أَنَّ مُحَمَّدًا عَبْدُهُ وَرَسُولُهُ', tr: 'Ashhadu an lā ilāha illa-llāhu waḥdahu lā sharīka lah, wa ashhadu anna Muḥammadan ‘abduhu wa rasūluh', fr: 'J’atteste qu’il n’y a de divinité qu’Allah, Seul, sans associé, et j’atteste que Muhammad est Son serviteur et Son messager. (Les huit portes du Paradis s’ouvrent pour lui.)', ref: 'Sahih Muslim 234' },
  { id: 'libas', cat: 'maison', title: 'En mettant un vêtement', when: 'En s’habillant', ar: 'الْحَمْدُ لِلَّهِ الَّذِي كَسَانِي هَذَا الثَّوْبَ، وَرَزَقَنِيهِ مِنْ غَيْرِ حَوْلٍ مِنِّي وَلَا قُوَّةٍ', tr: 'Al-ḥamdu li-llāhi-lladhī kasānī hādha-th-thawb, wa razaqanīhi min ghayri ḥawlin minnī wa lā quwwah', fr: 'Louange à Allah qui m’a vêtu de ce vêtement et me l’a accordé sans force ni puissance de ma part.', ref: 'Sunan Abi Dawud 4023' },
  { id: 'atas', cat: 'maison', title: 'L’éternuement', when: 'Après un éternuement', ar: 'الْحَمْدُ لِلَّهِ — يَرْحَمُكَ اللَّهُ — يَهْدِيكُمُ اللَّهُ وَيُصْلِحُ بَالَكُمْ', tr: 'Al-ḥamdu li-llāh — Yarḥamuka-llāh — Yahdīkumu-llāhu wa yuṣliḥu bālakum', fr: 'Celui qui éternue dit « Louange à Allah » ; on lui répond « Qu’Allah te fasse miséricorde » ; il répond « Qu’Allah vous guide et améliore votre état ».', ref: 'Sahih al-Bukhari 6224' },
  { id: 'majlis', cat: 'maison', title: 'Expiation d’une assemblée', when: 'Avant de quitter une assemblée', ar: 'سُبْحَانَكَ اللَّهُمَّ وَبِحَمْدِكَ، أَشْهَدُ أَنْ لَا إِلَهَ إِلَّا أَنْتَ، أَسْتَغْفِرُكَ وَأَتُوبُ إِلَيْكَ', tr: 'Subḥānaka-llāhumma wa bi-ḥamdik, ashhadu an lā ilāha illā ant, astaghfiruka wa atūbu ilayk', fr: 'Gloire à Toi, ô Allah, et louange à Toi. J’atteste qu’il n’y a de divinité que Toi ; je Te demande pardon et je reviens à Toi.', ref: 'Jami‘ at-Tirmidhi 3433' },
  { id: 'ghadab', cat: 'maison', title: 'Contre la colère', when: 'Sous le coup de la colère', ar: 'أَعُوذُ بِاللَّهِ مِنَ الشَّيْطَانِ الرَّجِيمِ', tr: 'A‘ūdhu bi-llāhi mina-sh-shayṭāni-r-rajīm', fr: 'Je cherche refuge auprès d’Allah contre Satan le maudit. (« Je connais une parole qui, s’il la disait, ferait partir ce qu’il ressent. »)', ref: 'Sahih al-Bukhari 3282' },

  // ── Voyage ──────────────────────────────────────────────────
  { id: 'safar', cat: 'voyage', title: 'L’invocation du voyage', when: 'Une fois installé sur sa monture, après 3 takbir', ar: 'اللَّهُ أَكْبَرُ، اللَّهُ أَكْبَرُ، اللَّهُ أَكْبَرُ، سُبْحَانَ الَّذِي سَخَّرَ لَنَا هَذَا وَمَا كُنَّا لَهُ مُقْرِنِينَ، وَإِنَّا إِلَى رَبِّنَا لَمُنْقَلِبُونَ، اللَّهُمَّ إِنَّا نَسْأَلُكَ فِي سَفَرِنَا هَذَا الْبِرَّ وَالتَّقْوَى، وَمِنَ الْعَمَلِ مَا تَرْضَى، اللَّهُمَّ هَوِّنْ عَلَيْنَا سَفَرَنَا هَذَا وَاطْوِ عَنَّا بُعْدَهُ، اللَّهُمَّ أَنْتَ الصَّاحِبُ فِي السَّفَرِ، وَالْخَلِيفَةُ فِي الْأَهْلِ، اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنْ وَعْثَاءِ السَّفَرِ، وَكَآبَةِ الْمَنْظَرِ، وَسُوءِ الْمُنْقَلَبِ فِي الْمَالِ وَالْأَهْلِ', tr: 'Allāhu akbar (×3). Subḥāna-lladhī sakhkhara lanā hādhā wa mā kunnā lahu muqrinīn, wa innā ilā rabbinā la-munqalibūn. Allāhumma innā nas’aluka fī safarinā hādha-l-birra wa-t-taqwā, wa mina-l-‘amali mā tarḍā. Allāhumma hawwin ‘alaynā safaranā hādhā wa-ṭwi ‘annā bu‘dah. Allāhumma anta-ṣ-ṣāḥibu fi-s-safar, wa-l-khalīfatu fi-l-ahl. Allāhumma innī a‘ūdhu bika min wa‘thā’i-s-safar, wa ka’ābati-l-manẓar, wa sū’i-l-munqalabi fi-l-māli wa-l-ahl', fr: 'Allah est le plus grand (×3). Gloire à Celui qui a mis ceci à notre service alors que nous n’aurions pu le maîtriser ; c’est vers notre Seigneur que nous retournerons. Ô Allah, nous Te demandons dans ce voyage la piété et la crainte, et des œuvres qui Te plaisent. Ô Allah, facilite-nous ce voyage et raccourcis-en la distance. Ô Allah, Tu es le Compagnon du voyage et Celui qui veille sur la famille. Ô Allah, je cherche refuge auprès de Toi contre la pénibilité du voyage, les spectacles affligeants et un mauvais retour pour les biens et la famille.', ref: 'Sahih Muslim 1342' },
  { id: 'ayibun', cat: 'voyage', title: 'Au retour de voyage', when: 'Au retour (ajouté à l’invocation du voyage)', ar: 'آيِبُونَ تَائِبُونَ عَابِدُونَ لِرَبِّنَا حَامِدُونَ', tr: 'Āyibūna tā’ibūna ‘ābidūna li-rabbinā ḥāmidūn', fr: 'Nous revenons, repentants, adorateurs, et louant notre Seigneur.', ref: 'Sahih Muslim 1342 ; Sahih al-Bukhari 1797' },
  { id: 'suud', cat: 'voyage', title: 'En montant et en descendant', when: 'En montée / en descente', ar: 'اللَّهُ أَكْبَرُ — سُبْحَانَ اللَّهِ', tr: 'Allāhu akbar — Subḥāna-llāh', fr: 'Les Compagnons disaient « Allah est le plus grand » en montant et « Gloire à Allah » en descendant.', ref: 'Sahih al-Bukhari 2993' },
  { id: 'manzil', cat: 'voyage', title: 'En faisant halte', when: 'À une étape ; aussi le soir', ar: 'أَعُوذُ بِكَلِمَاتِ اللَّهِ التَّامَّاتِ مِنْ شَرِّ مَا خَلَقَ', tr: 'A‘ūdhu bi-kalimāti-llāhi-t-tāmmāti min sharri mā khalaq', fr: 'Je cherche refuge dans les paroles parfaites d’Allah contre le mal de ce qu’Il a créé. (Rien ne lui nuira jusqu’à ce qu’il quitte ce lieu.)', ref: 'Sahih Muslim 2708 ; Sahih Muslim 2709' },
  { id: 'wada', cat: 'voyage', title: 'Faire ses adieux au voyageur', when: 'Pour celui qui part', ar: 'أَسْتَوْدِعُ اللَّهَ دِينَكَ، وَأَمَانَتَكَ، وَخَوَاتِيمَ عَمَلِكَ', tr: 'Astawdi‘u-llāha dīnaka wa amānataka wa khawātīma ‘amalik', fr: 'Je confie à Allah ta religion, ta fidélité (ce dont tu as la charge) et la fin de tes œuvres.', ref: 'Sunan Abi Dawud 2600' },

  // ── Mosquée & adhan ─────────────────────────────────────────
  { id: 'masjid', cat: 'mosquee', title: 'Entrer et sortir de la mosquée', when: 'En entrant / en sortant de la mosquée', ar: 'اللَّهُمَّ افْتَحْ لِي أَبْوَابَ رَحْمَتِكَ — اللَّهُمَّ إِنِّي أَسْأَلُكَ مِنْ فَضْلِكَ', tr: 'Allāhumma-ftaḥ lī abwāba raḥmatik — Allāhumma innī as’aluka min faḍlik', fr: 'Ô Allah, ouvre-moi les portes de Ta miséricorde. — (En sortant) Ô Allah, je Te demande de Ta grâce.', ref: 'Sahih Muslim 713' },
  { id: 'azim', cat: 'mosquee', title: 'Refuge en entrant à la mosquée', when: 'En entrant à la mosquée', ar: 'أَعُوذُ بِاللَّهِ الْعَظِيمِ، وَبِوَجْهِهِ الْكَرِيمِ، وَسُلْطَانِهِ الْقَدِيمِ، مِنَ الشَّيْطَانِ الرَّجِيمِ', tr: 'A‘ūdhu bi-llāhi-l-‘aẓīm, wa bi-wajhihi-l-karīm, wa sulṭānihi-l-qadīm, mina-sh-shayṭāni-r-rajīm', fr: 'Je cherche refuge auprès d’Allah l’Immense, par Son noble Visage et Son autorité éternelle, contre Satan le maudit.', ref: 'Sunan Abi Dawud 466' },
  { id: 'nur', cat: 'mosquee', title: 'Ô Allah, mets de la lumière dans mon cœur', when: 'En allant à la prière, la nuit', ar: 'اللَّهُمَّ اجْعَلْ فِي قَلْبِي نُورًا، وَفِي بَصَرِي نُورًا، وَفِي سَمْعِي نُورًا، وَعَنْ يَمِينِي نُورًا، وَعَنْ يَسَارِي نُورًا، وَفَوْقِي نُورًا، وَتَحْتِي نُورًا، وَأَمَامِي نُورًا، وَخَلْفِي نُورًا، وَاجْعَلْ لِي نُورًا', tr: 'Allāhumma-j‘al fī qalbī nūrā, wa fī baṣarī nūrā, wa fī sam‘ī nūrā, wa ‘an yamīnī nūrā, wa ‘an yasārī nūrā, wa fawqī nūrā, wa taḥtī nūrā, wa amāmī nūrā, wa khalfī nūrā, wa-j‘al lī nūrā', fr: 'Ô Allah, mets de la lumière dans mon cœur, dans ma vue, dans mon ouïe, à ma droite, à ma gauche, au-dessus de moi, au-dessous de moi, devant moi, derrière moi, et accorde-moi une lumière.', ref: 'Sahih al-Bukhari 6316 ; Sahih Muslim 763' },
  { id: 'adhan', cat: 'mosquee', title: 'Après l’adhan', when: 'Après avoir entendu l’appel', ar: 'اللَّهُمَّ رَبَّ هَذِهِ الدَّعْوَةِ التَّامَّةِ، وَالصَّلَاةِ الْقَائِمَةِ، آتِ مُحَمَّدًا الْوَسِيلَةَ وَالْفَضِيلَةَ، وَابْعَثْهُ مَقَامًا مَحْمُودًا الَّذِي وَعَدْتَهُ', tr: 'Allāhumma rabba hādhihi-d-da‘wati-t-tāmma, wa-ṣ-ṣalāti-l-qā’ima, āti Muḥammadani-l-wasīlata wa-l-faḍīla, wa-b‘ath-hu maqāman maḥmūdani-lladhī wa‘adtah', fr: 'Ô Allah, Seigneur de cet appel parfait et de la prière qui va être accomplie, accorde à Muhammad al-Wasila et l’excellence, et ressuscite-le à la station louable que Tu lui as promise.', ref: 'Sahih al-Bukhari 614' },
  { id: 'raditu', cat: 'mosquee', title: 'Agréé Allah comme Seigneur', when: 'En entendant le muezzin', ar: 'أَشْهَدُ أَنْ لَا إِلَهَ إِلَّا اللَّهُ وَحْدَهُ لَا شَرِيكَ لَهُ، وَأَنَّ مُحَمَّدًا عَبْدُهُ وَرَسُولُهُ، رَضِيتُ بِاللَّهِ رَبًّا، وَبِمُحَمَّدٍ رَسُولًا، وَبِالْإِسْلَامِ دِينًا', tr: 'Ashhadu an lā ilāha illa-llāhu waḥdahu lā sharīka lah, wa anna Muḥammadan ‘abduhu wa rasūluh, raḍītu bi-llāhi rabbā, wa bi-Muḥammadin rasūlā, wa bi-l-islāmi dīnā', fr: 'J’atteste qu’il n’y a de divinité qu’Allah, Seul, sans associé, et que Muhammad est Son serviteur et Son messager. J’agrée Allah comme Seigneur, Muhammad comme messager et l’islam comme religion.', ref: 'Sahih Muslim 386' },

  // ── Dans la prière ──────────────────────────────────────────
  { id: 'istiftah', cat: 'priere', title: 'Ouverture de la prière', when: 'Après le takbir d’ouverture', ar: 'سُبْحَانَكَ اللَّهُمَّ وَبِحَمْدِكَ، وَتَبَارَكَ اسْمُكَ، وَتَعَالَى جَدُّكَ، وَلَا إِلَهَ غَيْرُكَ', tr: 'Subḥānaka-llāhumma wa bi-ḥamdik, wa tabāraka-smuk, wa ta‘ālā jadduk, wa lā ilāha ghayruk', fr: 'Gloire à Toi, ô Allah, et louange à Toi ; béni soit Ton nom, exaltée soit Ta majesté, et il n’y a de divinité que Toi.', ref: 'Sunan Abi Dawud 775' },
  { id: 'ruku-sujud', cat: 'priere', title: 'Inclinaison et prosternation', when: 'Ruku‘ / sujud', ar: 'سُبْحَانَ رَبِّيَ الْعَظِيمِ — سُبْحَانَ رَبِّيَ الْأَعْلَى', tr: 'Subḥāna rabbiya-l-‘aẓīm — Subḥāna rabbiya-l-a‘lā', fr: 'Gloire à mon Seigneur l’Immense (en inclinaison). — Gloire à mon Seigneur le Très-Haut (en prosternation).', ref: 'Sunan Abi Dawud 874 ; Sahih Muslim 772' },
  { id: 'jalsa', cat: 'priere', title: 'Entre les deux prosternations', when: 'Assis entre les deux sujud', ar: 'رَبِّ اغْفِرْ لِي، رَبِّ اغْفِرْ لِي', tr: 'Rabbi-ghfir lī, rabbi-ghfir lī', fr: 'Seigneur, pardonne-moi ; Seigneur, pardonne-moi.', ref: 'Sunan Ibn Majah 897 ; Sunan Abi Dawud 874' },
  { id: 'salat-ibrahimiyya', cat: 'priere', title: 'La prière sur le Prophète ﷺ (as-salat al-ibrahimiyya)', when: 'Dans le dernier tashahhud', ar: 'اللَّهُمَّ صَلِّ عَلَى مُحَمَّدٍ وَعَلَى آلِ مُحَمَّدٍ، كَمَا صَلَّيْتَ عَلَى إِبْرَاهِيمَ وَعَلَى آلِ إِبْرَاهِيمَ، إِنَّكَ حَمِيدٌ مَجِيدٌ، اللَّهُمَّ بَارِكْ عَلَى مُحَمَّدٍ وَعَلَى آلِ مُحَمَّدٍ، كَمَا بَارَكْتَ عَلَى إِبْرَاهِيمَ وَعَلَى آلِ إِبْرَاهِيمَ، إِنَّكَ حَمِيدٌ مَجِيدٌ', tr: 'Allāhumma ṣalli ‘alā Muḥammadin wa ‘alā āli Muḥammad, kamā ṣallayta ‘alā Ibrāhīma wa ‘alā āli Ibrāhīm, innaka ḥamīdun majīd. Allāhumma bārik ‘alā Muḥammadin wa ‘alā āli Muḥammad, kamā bārakta ‘alā Ibrāhīma wa ‘alā āli Ibrāhīm, innaka ḥamīdun majīd', fr: 'Ô Allah, prie sur Muhammad et sur la famille de Muhammad comme Tu as prié sur Ibrahim et sur la famille d’Ibrahim ; Tu es digne de louange et de gloire. Ô Allah, bénis Muhammad et la famille de Muhammad comme Tu as béni Ibrahim et la famille d’Ibrahim ; Tu es digne de louange et de gloire.', ref: 'Sahih al-Bukhari 3370' },
  { id: 'arba', cat: 'priere', title: 'Refuge contre quatre choses', when: 'Après le dernier tashahhud, avant le salam', ar: 'اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنْ عَذَابِ جَهَنَّمَ، وَمِنْ عَذَابِ الْقَبْرِ، وَمِنْ فِتْنَةِ الْمَحْيَا وَالْمَمَاتِ، وَمِنْ شَرِّ فِتْنَةِ الْمَسِيحِ الدَّجَّالِ', tr: 'Allāhumma innī a‘ūdhu bika min ‘adhābi jahannam, wa min ‘adhābi-l-qabr, wa min fitnati-l-maḥyā wa-l-mamāt, wa min sharri fitnati-l-masīḥi-d-dajjāl', fr: 'Ô Allah, je cherche refuge auprès de Toi contre le châtiment de l’Enfer, le châtiment de la tombe, l’épreuve de la vie et de la mort, et le mal de l’épreuve du faux Messie.', ref: 'Sahih Muslim 588' },
  { id: 'abubakr', cat: 'priere', title: 'L’invocation enseignée à Abu Bakr', when: 'Dans la prière', ar: 'اللَّهُمَّ إِنِّي ظَلَمْتُ نَفْسِي ظُلْمًا كَثِيرًا، وَلَا يَغْفِرُ الذُّنُوبَ إِلَّا أَنْتَ، فَاغْفِرْ لِي مَغْفِرَةً مِنْ عِنْدِكَ، وَارْحَمْنِي، إِنَّكَ أَنْتَ الْغَفُورُ الرَّحِيمُ', tr: 'Allāhumma innī ẓalamtu nafsī ẓulman kathīrā, wa lā yaghfiru-dh-dhunūba illā ant, fa-ghfir lī maghfiratan min ‘indik, wa-rḥamnī, innaka anta-l-ghafūru-r-raḥīm', fr: 'Ô Allah, je me suis fait beaucoup de tort et nul ne pardonne les péchés hormis Toi : accorde-moi un pardon venant de Toi et fais-moi miséricorde ; Tu es le Pardonneur, le Miséricordieux.', ref: 'Sahih al-Bukhari 834' },
  { id: 'qunut', cat: 'priere', title: 'Qunut du witr', when: 'Dans le witr', ar: 'اللَّهُمَّ اهْدِنِي فِيمَنْ هَدَيْتَ، وَعَافِنِي فِيمَنْ عَافَيْتَ، وَتَوَلَّنِي فِيمَنْ تَوَلَّيْتَ، وَبَارِكْ لِي فِيمَا أَعْطَيْتَ، وَقِنِي شَرَّ مَا قَضَيْتَ، إِنَّكَ تَقْضِي وَلَا يُقْضَى عَلَيْكَ، وَإِنَّهُ لَا يَذِلُّ مَنْ وَالَيْتَ، وَلَا يَعِزُّ مَنْ عَادَيْتَ، تَبَارَكْتَ رَبَّنَا وَتَعَالَيْتَ', tr: 'Allāhumma-hdinī fīman hadayt, wa ‘āfinī fīman ‘āfayt, wa tawallanī fīman tawallayt, wa bārik lī fīmā a‘ṭayt, wa qinī sharra mā qaḍayt, innaka taqḍī wa lā yuqḍā ‘alayk, wa innahu lā yadhillu man wālayt, wa lā ya‘izzu man ‘ādayt, tabārakta rabbanā wa ta‘ālayt', fr: 'Ô Allah, guide-moi parmi ceux que Tu as guidés, préserve-moi parmi ceux que Tu as préservés, prends-moi en charge parmi ceux que Tu as pris en charge, bénis-moi dans ce que Tu m’as donné et protège-moi du mal de ce que Tu as décrété. C’est Toi qui décrètes et nul ne décrète contre Toi ; celui que Tu soutiens n’est jamais humilié et celui que Tu prends pour ennemi n’est jamais honoré. Béni sois-Tu, notre Seigneur, et exalté.', ref: 'Sunan Abi Dawud 1425' },

  // ── Après la prière ─────────────────────────────────────────
  { id: 'salam', cat: 'apres-priere', title: 'Juste après le salam', when: 'Après chaque prière obligatoire', ar: 'أَسْتَغْفِرُ اللَّهَ، أَسْتَغْفِرُ اللَّهَ، أَسْتَغْفِرُ اللَّهَ، اللَّهُمَّ أَنْتَ السَّلَامُ وَمِنْكَ السَّلَامُ، تَبَارَكْتَ ذَا الْجَلَالِ وَالْإِكْرَامِ', tr: 'Astaghfiru-llāh (×3). Allāhumma anta-s-salām wa minka-s-salām, tabārakta dha-l-jalāli wa-l-ikrām', fr: 'Je demande pardon à Allah (×3). Ô Allah, Tu es la Paix et de Toi vient la paix ; béni sois-Tu, ô Détenteur de la majesté et de la générosité.', ref: 'Sahih Muslim 591' },
  { id: 'la-mani', cat: 'apres-priere', title: 'Nul ne retient ce que Tu donnes', when: 'Après chaque prière obligatoire', ar: 'لَا إِلَهَ إِلَّا اللَّهُ وَحْدَهُ لَا شَرِيكَ لَهُ، لَهُ الْمُلْكُ وَلَهُ الْحَمْدُ، وَهُوَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ، اللَّهُمَّ لَا مَانِعَ لِمَا أَعْطَيْتَ، وَلَا مُعْطِيَ لِمَا مَنَعْتَ، وَلَا يَنْفَعُ ذَا الْجَدِّ مِنْكَ الْجَدُّ', tr: 'Lā ilāha illa-llāhu waḥdahu lā sharīka lah, lahu-l-mulku wa lahu-l-ḥamd, wa huwa ‘alā kulli shay’in qadīr. Allāhumma lā māni‘a limā a‘ṭayt, wa lā mu‘ṭiya limā mana‘t, wa lā yanfa‘u dha-l-jaddi minka-l-jadd', fr: 'Il n’y a de divinité qu’Allah, Seul, sans associé… Ô Allah, nul ne peut retenir ce que Tu donnes ni donner ce que Tu retiens, et la fortune du fortuné ne lui sert à rien auprès de Toi.', ref: 'Sahih al-Bukhari 844' },
  { id: 'tasbih-33', cat: 'apres-priere', title: 'Tasbih, tahmid, takbir', when: 'Après chaque prière', reps: 33, ar: 'سُبْحَانَ اللَّهِ (٣٣) — الْحَمْدُ لِلَّهِ (٣٣) — اللَّهُ أَكْبَرُ (٣٣) — لَا إِلَهَ إِلَّا اللَّهُ وَحْدَهُ لَا شَرِيكَ لَهُ، لَهُ الْمُلْكُ وَلَهُ الْحَمْدُ وَهُوَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ', tr: 'Subḥāna-llāh (33) — Al-ḥamdu li-llāh (33) — Allāhu akbar (33) — Lā ilāha illa-llāhu waḥdahu lā sharīka lah, lahu-l-mulku wa lahu-l-ḥamdu wa huwa ‘alā kulli shay’in qadīr', fr: 'Gloire à Allah (33), louange à Allah (33), Allah est le plus grand (33), et pour compléter la centaine : « Il n’y a de divinité qu’Allah, Seul, sans associé… ». Ses fautes sont pardonnées, fussent-elles comme l’écume de la mer.', ref: 'Sahih Muslim 597' },
  { id: 'ainni', cat: 'apres-priere', title: 'Aide-moi à T’évoquer', when: 'À la fin de chaque prière', ar: 'اللَّهُمَّ أَعِنِّي عَلَى ذِكْرِكَ، وَشُكْرِكَ، وَحُسْنِ عِبَادَتِكَ', tr: 'Allāhumma a‘innī ‘alā dhikrik, wa shukrik, wa ḥusni ‘ibādatik', fr: 'Ô Allah, aide-moi à T’évoquer, à Te remercier et à bien T’adorer.', ref: 'Sunan Abi Dawud 1522' },
  { id: 'muawwidhat-salat', cat: 'apres-priere', title: 'Les sourates protectrices', when: 'Après chaque prière', ar: 'قُلْ هُوَ اللَّهُ أَحَدٌ… — قُلْ أَعُوذُ بِرَبِّ الْفَلَقِ… — قُلْ أَعُوذُ بِرَبِّ النَّاسِ…', tr: 'Qul huwa-llāhu aḥad… — Qul a‘ūdhu bi-rabbi-l-falaq… — Qul a‘ūdhu bi-rabbi-n-nās…', fr: '« Le Messager d’Allah ﷺ m’a ordonné de réciter les mu‘awwidhat à la fin de chaque prière. » (‘Uqba ibn ‘Amir)', ref: 'Sunan Abi Dawud 1523 ; Coran 112–114' },
  { id: 'jubn', cat: 'apres-priere', title: 'Refuge contre la lâcheté', when: 'À la fin de la prière', ar: 'اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنَ الْجُبْنِ، وَأَعُوذُ بِكَ أَنْ أُرَدَّ إِلَى أَرْذَلِ الْعُمُرِ، وَأَعُوذُ بِكَ مِنْ فِتْنَةِ الدُّنْيَا، وَأَعُوذُ بِكَ مِنْ عَذَابِ الْقَبْرِ', tr: 'Allāhumma innī a‘ūdhu bika mina-l-jubn, wa a‘ūdhu bika an uradda ilā ardhali-l-‘umur, wa a‘ūdhu bika min fitnati-d-dunyā, wa a‘ūdhu bika min ‘adhābi-l-qabr', fr: 'Ô Allah, je cherche refuge auprès de Toi contre la lâcheté, contre le fait d’être ramené à l’âge le plus vil, contre l’épreuve de ce bas monde et contre le châtiment de la tombe.', ref: 'Sahih al-Bukhari 2822' },
  { id: 'ilm-nafi', cat: 'apres-priere', title: 'Science utile et subsistance licite', when: 'Après le salam de la prière du Fajr', ar: 'اللَّهُمَّ إِنِّي أَسْأَلُكَ عِلْمًا نَافِعًا، وَرِزْقًا طَيِّبًا، وَعَمَلًا مُتَقَبَّلًا', tr: 'Allāhumma innī as’aluka ‘ilman nāfi‘ā, wa rizqan ṭayyibā, wa ‘amalan mutaqabbalā', fr: 'Ô Allah, je Te demande une science utile, une subsistance pure et des œuvres acceptées.', ref: 'Sunan Ibn Majah 925' },

  // ── Protection ──────────────────────────────────────────────
  { id: 'enfants', cat: 'protection', title: 'Protéger ses enfants', when: 'Pour les enfants (le Prophète ﷺ protégeait ainsi al-Hasan et al-Husayn)', ar: 'أَعُوذُ بِكَلِمَاتِ اللَّهِ التَّامَّةِ، مِنْ كُلِّ شَيْطَانٍ وَهَامَّةٍ، وَمِنْ كُلِّ عَيْنٍ لَامَّةٍ', tr: 'A‘ūdhu bi-kalimāti-llāhi-t-tāmma, min kulli shayṭānin wa hāmma, wa min kulli ‘aynin lāmma', fr: 'Je cherche refuge dans les paroles parfaites d’Allah contre tout démon, toute bête nuisible et tout mauvais œil. (Pour un enfant, on dit « u‘īdhuka » : je te place sous la protection…)', ref: 'Sahih al-Bukhari 3371' },
  { id: 'nuhur', cat: 'protection', title: 'Face à la crainte d’un groupe', when: 'Quand on craint des gens', ar: 'اللَّهُمَّ إِنَّا نَجْعَلُكَ فِي نُحُورِهِمْ، وَنَعُوذُ بِكَ مِنْ شُرُورِهِمْ', tr: 'Allāhumma innā naj‘aluka fī nuḥūrihim, wa na‘ūdhu bika min shurūrihim', fr: 'Ô Allah, nous Te plaçons face à eux et nous cherchons refuge auprès de Toi contre leurs maux.', ref: 'Sunan Abi Dawud 1537' },
  { id: 'zawal', cat: 'protection', title: 'Refuge contre la disparition des bienfaits', when: 'À tout moment', ar: 'اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنْ زَوَالِ نِعْمَتِكَ، وَتَحَوُّلِ عَافِيَتِكَ، وَفُجَاءَةِ نِقْمَتِكَ، وَجَمِيعِ سَخَطِكَ', tr: 'Allāhumma innī a‘ūdhu bika min zawāli ni‘matik, wa taḥawwuli ‘āfiyatik, wa fujā’ati niqmatik, wa jamī‘i sakhaṭik', fr: 'Ô Allah, je cherche refuge auprès de Toi contre la disparition de Ton bienfait, le retrait de Ta préservation, la soudaineté de Ton châtiment et tout ce qui suscite Ta colère.', ref: 'Sahih Muslim 2739' },
  { id: 'hasbuna', cat: 'protection', title: 'Allah nous suffit', when: 'Face à la menace ou à la peur', ar: 'حَسْبُنَا اللَّهُ وَنِعْمَ الْوَكِيلُ', tr: 'Ḥasbuna-llāhu wa ni‘ma-l-wakīl', fr: 'Allah nous suffit, et quel excellent Garant ! (Paroles d’Ibrahim jeté dans le feu, et de Muhammad ﷺ quand on lui dit que les gens s’étaient rassemblés contre eux.)', ref: 'Coran 3:173 ; Sahih al-Bukhari 4563' },

  // ── Détresse & anxiété ──────────────────────────────────────
  { id: 'karb', cat: 'detresse', title: 'L’invocation de l’angoisse', when: 'Dans l’angoisse', ar: 'لَا إِلَهَ إِلَّا اللَّهُ الْعَظِيمُ الْحَلِيمُ، لَا إِلَهَ إِلَّا اللَّهُ رَبُّ الْعَرْشِ الْعَظِيمِ، لَا إِلَهَ إِلَّا اللَّهُ رَبُّ السَّمَاوَاتِ وَرَبُّ الْأَرْضِ وَرَبُّ الْعَرْشِ الْكَرِيمِ', tr: 'Lā ilāha illa-llāhu-l-‘aẓīmu-l-ḥalīm, lā ilāha illa-llāhu rabbu-l-‘arshi-l-‘aẓīm, lā ilāha illa-llāhu rabbu-s-samāwāti wa rabbu-l-arḍi wa rabbu-l-‘arshi-l-karīm', fr: 'Il n’y a de divinité qu’Allah, l’Immense, le Longanime ; il n’y a de divinité qu’Allah, Seigneur du Trône immense ; il n’y a de divinité qu’Allah, Seigneur des cieux, Seigneur de la terre et Seigneur du Trône noble.', ref: 'Sahih al-Bukhari 6346 ; Sahih Muslim 2730' },
  { id: 'yunus', cat: 'detresse', title: 'L’invocation de Yunus (Jonas)', when: 'Dans l’épreuve', ar: 'لَا إِلَهَ إِلَّا أَنْتَ سُبْحَانَكَ إِنِّي كُنْتُ مِنَ الظَّالِمِينَ', tr: 'Lā ilāha illā anta subḥānaka innī kuntu mina-ẓ-ẓālimīn', fr: 'Il n’y a de divinité que Toi, gloire à Toi ! J’ai été du nombre des injustes.', ref: 'Coran 21:87 ; Jami‘ at-Tirmidhi 3505' },
  { id: 'hamm', cat: 'detresse', title: 'Contre le souci et la tristesse', when: 'Contre les soucis', ar: 'اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنَ الْهَمِّ وَالْحَزَنِ، وَالْعَجْزِ وَالْكَسَلِ، وَالْجُبْنِ وَالْبُخْلِ، وَضَلَعِ الدَّيْنِ، وَغَلَبَةِ الرِّجَالِ', tr: 'Allāhumma innī a‘ūdhu bika mina-l-hammi wa-l-ḥazan, wa-l-‘ajzi wa-l-kasal, wa-l-jubni wa-l-bukhl, wa ḍala‘i-d-dayn, wa ghalabati-r-rijāl', fr: 'Ô Allah, je cherche refuge auprès de Toi contre le souci et la tristesse, l’incapacité et la paresse, la lâcheté et l’avarice, le poids des dettes et la domination des hommes.', ref: 'Sahih al-Bukhari 6369' },
  { id: 'abduka', cat: 'detresse', title: 'Ô Allah, je suis Ton serviteur', when: 'Contre le chagrin et l’anxiété', ar: 'اللَّهُمَّ إِنِّي عَبْدُكَ، ابْنُ عَبْدِكَ، ابْنُ أَمَتِكَ، نَاصِيَتِي بِيَدِكَ، مَاضٍ فِيَّ حُكْمُكَ، عَدْلٌ فِيَّ قَضَاؤُكَ، أَسْأَلُكَ بِكُلِّ اسْمٍ هُوَ لَكَ، سَمَّيْتَ بِهِ نَفْسَكَ، أَوْ أَنْزَلْتَهُ فِي كِتَابِكَ، أَوْ عَلَّمْتَهُ أَحَدًا مِنْ خَلْقِكَ، أَوِ اسْتَأْثَرْتَ بِهِ فِي عِلْمِ الْغَيْبِ عِنْدَكَ، أَنْ تَجْعَلَ الْقُرْآنَ رَبِيعَ قَلْبِي، وَنُورَ صَدْرِي، وَجِلَاءَ حُزْنِي، وَذَهَابَ هَمِّي', tr: 'Allāhumma innī ‘abduk, ibnu ‘abdik, ibnu amatik, nāṣiyatī bi-yadik, māḍin fiyya ḥukmuk, ‘adlun fiyya qaḍā’uk, as’aluka bi-kulli-smin huwa lak, sammayta bihi nafsak, aw anzaltahu fī kitābik, aw ‘allamtahu aḥadan min khalqik, awi-sta’tharta bihi fī ‘ilmi-l-ghaybi ‘indak, an taj‘ala-l-qur’āna rabī‘a qalbī, wa nūra ṣadrī, wa jalā’a ḥuznī, wa dhahāba hammī', fr: 'Ô Allah, je suis Ton serviteur, fils de Ton serviteur et de Ta servante ; mon toupet est dans Ta main, Ton jugement s’accomplit en moi, Ton décret à mon égard est juste. Je Te demande, par chacun de Tes noms — que Tu T’es donné, révélé dans Ton Livre, enseigné à l’une de Tes créatures ou gardé dans la science de l’invisible auprès de Toi — de faire du Coran le printemps de mon cœur, la lumière de ma poitrine, ce qui dissipe ma tristesse et chasse mon souci.', ref: 'Musnad Ahmad 3712 (authentifié par al-Albani, as-Silsila as-Sahiha 199)' },
  { id: 'hayy-qayyum', cat: 'detresse', title: 'Ô Vivant, ô Subsistant', when: 'Quand une affaire accable', ar: 'يَا حَيُّ يَا قَيُّومُ، بِرَحْمَتِكَ أَسْتَغِيثُ', tr: 'Yā ḥayyu yā qayyūm, bi-raḥmatika astaghīth', fr: 'Ô Vivant, ô Toi qui subsistes par Toi-même, c’est Ta miséricorde que j’implore.', ref: 'Jami‘ at-Tirmidhi 3524 (hasan)' },
  { id: 'makrub', cat: 'detresse', title: 'L’invocation de celui qui est affligé', when: 'Dans la peine', ar: 'اللَّهُمَّ رَحْمَتَكَ أَرْجُو، فَلَا تَكِلْنِي إِلَى نَفْسِي طَرْفَةَ عَيْنٍ، وَأَصْلِحْ لِي شَأْنِي كُلَّهُ، لَا إِلَهَ إِلَّا أَنْتَ', tr: 'Allāhumma raḥmataka arjū, fa-lā takilnī ilā nafsī ṭarfata ‘ayn, wa aṣliḥ lī sha’nī kullah, lā ilāha illā ant', fr: 'Ô Allah, c’est Ta miséricorde que j’espère : ne me livre pas à moi-même, ne serait-ce qu’un clin d’œil, et rends bonne toute ma situation. Il n’y a de divinité que Toi.', ref: 'Sunan Abi Dawud 5090' },
  { id: 'dayn', cat: 'detresse', title: 'Contre les dettes', when: 'Pour être libéré des dettes', ar: 'اللَّهُمَّ اكْفِنِي بِحَلَالِكَ عَنْ حَرَامِكَ، وَأَغْنِنِي بِفَضْلِكَ عَمَّنْ سِوَاكَ', tr: 'Allāhumma-kfinī bi-ḥalālika ‘an ḥarāmik, wa aghninī bi-faḍlika ‘amman siwāk', fr: 'Ô Allah, suffis-moi par ce que Tu as rendu licite, pour que je n’aie pas besoin de l’illicite, et enrichis-moi par Ta grâce pour que je n’aie besoin de personne d’autre que Toi.', ref: 'Jami‘ at-Tirmidhi 3563 (hasan)' },

  // ── Maladie & épreuves ──────────────────────────────────────
  { id: 'la-bas', cat: 'maladie', title: 'En rendant visite à un malade', when: 'Auprès d’un malade', ar: 'لَا بَأْسَ، طَهُورٌ إِنْ شَاءَ اللَّهُ', tr: 'Lā ba’s, ṭahūrun in shā’a-llāh', fr: 'Ce n’est rien : c’est une purification, si Allah le veut.', ref: 'Sahih al-Bukhari 3616' },
  { id: 'yashfik', cat: 'maladie', title: 'Demander la guérison d’un malade', when: 'Auprès d’un malade', reps: 7, ar: 'أَسْأَلُ اللَّهَ الْعَظِيمَ، رَبَّ الْعَرْشِ الْعَظِيمِ، أَنْ يَشْفِيَكَ', tr: 'As’alu-llāha-l-‘aẓīm, rabba-l-‘arshi-l-‘aẓīm, an yashfiyak', fr: 'Je demande à Allah l’Immense, Seigneur du Trône immense, de te guérir.', ref: 'Sunan Abi Dawud 3106' },
  { id: 'ruqya', cat: 'maladie', title: 'Ô Allah, Seigneur des gens', when: 'En posant la main sur le malade', ar: 'اللَّهُمَّ رَبَّ النَّاسِ، أَذْهِبِ الْبَاسَ، اشْفِهِ وَأَنْتَ الشَّافِي، لَا شِفَاءَ إِلَّا شِفَاؤُكَ، شِفَاءً لَا يُغَادِرُ سَقَمًا', tr: 'Allāhumma rabba-n-nās, adhhibi-l-ba’s, ishfihi wa anta-sh-shāfī, lā shifā’a illā shifā’uk, shifā’an lā yughādiru saqamā', fr: 'Ô Allah, Seigneur des gens, fais disparaître le mal, guéris-le, Tu es Celui qui guérit ; il n’y a de guérison que Ta guérison, une guérison qui ne laisse aucune maladie.', ref: 'Sahih al-Bukhari 5743 ; Sahih Muslim 2191' },
  { id: 'waja', cat: 'maladie', title: 'Contre une douleur', when: 'La main posée sur l’endroit douloureux', reps: 7, ar: 'بِسْمِ اللَّهِ (٣) — أَعُوذُ بِاللَّهِ وَقُدْرَتِهِ مِنْ شَرِّ مَا أَجِدُ وَأُحَاذِرُ (٧)', tr: 'Bismi-llāh (×3) — A‘ūdhu bi-llāhi wa qudratihi min sharri mā ajidu wa uḥādhir (×7)', fr: 'Poser la main sur l’endroit douloureux, dire « Au nom d’Allah » trois fois, puis sept fois : « Je cherche refuge auprès d’Allah et de Sa puissance contre le mal de ce que je ressens et de ce que je redoute ».', ref: 'Sahih Muslim 2202' },
  { id: 'musiba', cat: 'maladie', title: 'Face à un malheur', when: 'Lors d’une épreuve ou d’un deuil', ar: 'إِنَّا لِلَّهِ وَإِنَّا إِلَيْهِ رَاجِعُونَ، اللَّهُمَّ أْجُرْنِي فِي مُصِيبَتِي، وَأَخْلِفْ لِي خَيْرًا مِنْهَا', tr: 'Innā li-llāhi wa innā ilayhi rāji‘ūn, Allāhumma’jurnī fī muṣībatī, wa akhlif lī khayran minhā', fr: 'Nous sommes à Allah et c’est vers Lui que nous retournerons. Ô Allah, récompense-moi dans mon épreuve et remplace-la pour moi par meilleur qu’elle.', ref: 'Sahih Muslim 918' },

  // ── Pardon ──────────────────────────────────────────────────
  { id: 'sayyid', cat: 'pardon', title: 'Sayyid al-istighfar', when: 'Matin et soir', ar: 'اللَّهُمَّ أَنْتَ رَبِّي لَا إِلَهَ إِلَّا أَنْتَ، خَلَقْتَنِي وَأَنَا عَبْدُكَ، وَأَنَا عَلَى عَهْدِكَ وَوَعْدِكَ مَا اسْتَطَعْتُ، أَعُوذُ بِكَ مِنْ شَرِّ مَا صَنَعْتُ، أَبُوءُ لَكَ بِنِعْمَتِكَ عَلَيَّ، وَأَبُوءُ بِذَنْبِي فَاغْفِرْ لِي، فَإِنَّهُ لَا يَغْفِرُ الذُّنُوبَ إِلَّا أَنْتَ', tr: 'Allāhumma anta rabbī lā ilāha illā ant, khalaqtanī wa ana ‘abduk, wa ana ‘alā ‘ahdika wa wa‘dika mā-staṭa‘t, a‘ūdhu bika min sharri mā ṣana‘t, abū’u laka bi-ni‘matika ‘alayy, wa abū’u bi-dhanbī fa-ghfir lī, fa-innahu lā yaghfiru-dh-dhunūba illā ant', fr: 'Ô Allah, Tu es mon Seigneur, il n’y a de divinité que Toi. Tu m’as créé et je suis Ton serviteur ; je reste fidèle à mon engagement envers Toi autant que je le peux. Je cherche refuge auprès de Toi contre le mal que j’ai commis. Je reconnais Tes bienfaits envers moi et je reconnais mon péché : pardonne-moi, car nul ne pardonne les péchés hormis Toi.', ref: 'Sahih al-Bukhari 6306' },
  { id: 'astaghfirullah', cat: 'pardon', title: 'Je demande pardon à Allah et me repens', when: 'Chaque jour', reps: 100, ar: 'أَسْتَغْفِرُ اللَّهَ وَأَتُوبُ إِلَيْهِ', tr: 'Astaghfiru-llāha wa atūbu ilayh', fr: 'Je demande pardon à Allah et je me repens à Lui. (Le Prophète ﷺ le disait plus de 70 fois par jour ; selon Muslim, 100 fois.)', ref: 'Sahih al-Bukhari 6307 ; Sahih Muslim 2702' },
  { id: 'tub-alayya', cat: 'pardon', title: 'Seigneur, pardonne-moi et accepte mon repentir', when: 'En assemblée', reps: 100, ar: 'رَبِّ اغْفِرْ لِي وَتُبْ عَلَيَّ، إِنَّكَ أَنْتَ التَّوَّابُ الرَّحِيمُ', tr: 'Rabbi-ghfir lī wa tub ‘alayy, innaka anta-t-tawwābu-r-raḥīm', fr: 'Seigneur, pardonne-moi et accepte mon repentir ; Tu es Celui qui accueille le repentir, le Miséricordieux. (On le comptait cent fois en une seule assemblée.)', ref: 'Sunan Abi Dawud 1516' },
  { id: 'hayy-istighfar', cat: 'pardon', title: 'Istighfar par le Vivant, le Subsistant', when: 'À tout moment', ar: 'أَسْتَغْفِرُ اللَّهَ الَّذِي لَا إِلَهَ إِلَّا هُوَ الْحَيُّ الْقَيُّومُ وَأَتُوبُ إِلَيْهِ', tr: 'Astaghfiru-llāha-lladhī lā ilāha illā huwa-l-ḥayyu-l-qayyūmu wa atūbu ilayh', fr: 'Je demande pardon à Allah, hormis qui il n’y a de divinité, le Vivant, le Subsistant, et je me repens à Lui.', ref: 'Sunan Abi Dawud 1517' },

  // ── Ramadan & jeûne ─────────────────────────────────────────
  { id: 'iftar', cat: 'ramadan', title: 'À la rupture du jeûne', when: 'Au moment de l’iftar', ar: 'ذَهَبَ الظَّمَأُ، وَابْتَلَّتِ الْعُرُوقُ، وَثَبَتَ الْأَجْرُ إِنْ شَاءَ اللَّهُ', tr: 'Dhahaba-ẓ-ẓama’, wa-btallati-l-‘urūq, wa thabata-l-ajru in shā’a-llāh', fr: 'La soif est partie, les veines sont humectées et la récompense est acquise, si Allah le veut.', ref: 'Sunan Abi Dawud 2357 (hasan)' },
  { id: 'aftara', cat: 'ramadan', title: 'Pour celui qui vous offre l’iftar', when: 'Chez ceux qui vous ont nourri', ar: 'أَفْطَرَ عِنْدَكُمُ الصَّائِمُونَ، وَأَكَلَ طَعَامَكُمُ الْأَبْرَارُ، وَصَلَّتْ عَلَيْكُمُ الْمَلَائِكَةُ', tr: 'Afṭara ‘indakumu-ṣ-ṣā’imūn, wa akala ṭa‘āmakumu-l-abrār, wa ṣallat ‘alaykumu-l-malā’ika', fr: 'Que les jeûneurs rompent leur jeûne chez vous, que les pieux mangent votre nourriture et que les anges prient pour vous.', ref: 'Sunan Abi Dawud 3854' },
  { id: 'saim', cat: 'ramadan', title: 'Face à l’insulte pendant le jeûne', when: 'Si quelqu’un vous insulte en jeûnant', reps: 2, ar: 'إِنِّي صَائِمٌ', tr: 'Innī ṣā’im', fr: 'Je jeûne. (À dire deux fois, au lieu de répondre.)', ref: 'Sahih al-Bukhari 1894' },
  { id: 'afw', cat: 'ramadan', title: 'Laylat al-Qadr', when: 'Nuits de Ramadan (Laylat al-Qadr)', ar: 'اللَّهُمَّ إِنَّكَ عَفُوٌّ تُحِبُّ الْعَفْوَ فَاعْفُ عَنِّي', tr: 'Allāhumma innaka ‘afuwwun tuḥibbu-l-‘afwa fa‘fu ‘annī', fr: 'Ô Allah, Tu es Celui qui efface les fautes, Tu aimes effacer : efface donc mes fautes.', note: 'Certaines éditions de Tirmidhi ajoutent « karīm » (‘afuwwun karīm).', ref: 'Jami‘ at-Tirmidhi 3513' },

  // ── Pluie & vent ────────────────────────────────────────────
  { id: 'sayyiban', cat: 'pluie', title: 'Quand il pleut', when: 'En voyant la pluie', ar: 'اللَّهُمَّ صَيِّبًا نَافِعًا', tr: 'Allāhumma ṣayyiban nāfi‘ā', fr: 'Ô Allah, (fais que ce soit) une pluie bienfaisante.', ref: 'Sahih al-Bukhari 1032' },
  { id: 'mutirna', cat: 'pluie', title: 'Après la pluie', when: 'Après la pluie', ar: 'مُطِرْنَا بِفَضْلِ اللَّهِ وَرَحْمَتِهِ', tr: 'Muṭirnā bi-faḍli-llāhi wa raḥmatih', fr: 'Nous avons reçu la pluie par la grâce d’Allah et Sa miséricorde.', ref: 'Sahih al-Bukhari 846' },
  { id: 'aghithna', cat: 'pluie', title: 'Demander la pluie', when: 'En période de sécheresse', reps: 3, ar: 'اللَّهُمَّ أَغِثْنَا، اللَّهُمَّ أَغِثْنَا، اللَّهُمَّ أَغِثْنَا', tr: 'Allāhumma aghithnā (×3)', fr: 'Ô Allah, accorde-nous la pluie (×3).', ref: 'Sahih al-Bukhari 1014' },
  { id: 'hawalayna', cat: 'pluie', title: 'Quand la pluie est excessive', when: 'Pluie trop abondante', ar: 'اللَّهُمَّ حَوَالَيْنَا وَلَا عَلَيْنَا، اللَّهُمَّ عَلَى الْآكَامِ وَالظِّرَابِ، وَبُطُونِ الْأَوْدِيَةِ، وَمَنَابِتِ الشَّجَرِ', tr: 'Allāhumma ḥawālaynā wa lā ‘alaynā, Allāhumma ‘ala-l-ākāmi wa-ẓ-ẓirāb, wa buṭūni-l-awdiya, wa manābiti-sh-shajar', fr: 'Ô Allah, autour de nous et non sur nous ; ô Allah, sur les collines et les hauteurs, au fond des vallées et là où poussent les arbres.', ref: 'Sahih al-Bukhari 1014' },
  { id: 'rih', cat: 'pluie', title: 'Quand le vent souffle fort', when: 'Par grand vent', ar: 'اللَّهُمَّ إِنِّي أَسْأَلُكَ خَيْرَهَا، وَخَيْرَ مَا فِيهَا، وَخَيْرَ مَا أُرْسِلَتْ بِهِ، وَأَعُوذُ بِكَ مِنْ شَرِّهَا، وَشَرِّ مَا فِيهَا، وَشَرِّ مَا أُرْسِلَتْ بِهِ', tr: 'Allāhumma innī as’aluka khayrahā, wa khayra mā fīhā, wa khayra mā ursilat bih, wa a‘ūdhu bika min sharrihā, wa sharri mā fīhā, wa sharri mā ursilat bih', fr: 'Ô Allah, je Te demande son bien, le bien de ce qu’il contient et le bien de ce avec quoi il a été envoyé ; je cherche refuge auprès de Toi contre son mal, le mal de ce qu’il contient et le mal de ce avec quoi il a été envoyé.', ref: 'Sahih Muslim 899' },

  // ── Famille & relations ─────────────────────────────────────
  { id: 'walidayn', cat: 'famille', title: 'Pour ses parents', when: 'Pour ses parents', ar: 'رَبِّ ارْحَمْهُمَا كَمَا رَبَّيَانِي صَغِيرًا', tr: 'Rabbi-rḥamhumā kamā rabbayānī ṣaghīrā', fr: 'Seigneur, fais-leur miséricorde comme ils m’ont élevé tout petit.', ref: 'Coran 17:24' },
  { id: 'zawaj', cat: 'famille', title: 'Féliciter les mariés', when: 'Pour un nouveau marié', ar: 'بَارَكَ اللَّهُ لَكَ، وَبَارَكَ عَلَيْكَ، وَجَمَعَ بَيْنَكُمَا فِي خَيْرٍ', tr: 'Bāraka-llāhu lak, wa bāraka ‘alayk, wa jama‘a baynakumā fī khayr', fr: 'Qu’Allah te bénisse, qu’Il répande Sa bénédiction sur toi et qu’Il vous unisse dans le bien.', ref: 'Sunan Abi Dawud 2130' },
  { id: 'jazak', cat: 'famille', title: 'Remercier un bienfaiteur', when: 'Quand on vous rend service', ar: 'جَزَاكَ اللَّهُ خَيْرًا', tr: 'Jazāka-llāhu khayrā', fr: 'Qu’Allah te récompense par le bien. (« Celui qui dit cela a pleinement remercié. »)', ref: 'Jami‘ at-Tirmidhi 2035 (hasan)' },

  // ── Défunts & cimetière ─────────────────────────────────────
  { id: 'janaza', cat: 'defunts', title: 'Prière sur le défunt', when: 'Dans la prière funéraire', ar: 'اللَّهُمَّ اغْفِرْ لَهُ وَارْحَمْهُ، وَعَافِهِ وَاعْفُ عَنْهُ، وَأَكْرِمْ نُزُلَهُ، وَوَسِّعْ مُدْخَلَهُ، وَاغْسِلْهُ بِالْمَاءِ وَالثَّلْجِ وَالْبَرَدِ، وَنَقِّهِ مِنَ الْخَطَايَا كَمَا نَقَّيْتَ الثَّوْبَ الْأَبْيَضَ مِنَ الدَّنَسِ، وَأَبْدِلْهُ دَارًا خَيْرًا مِنْ دَارِهِ، وَأَهْلًا خَيْرًا مِنْ أَهْلِهِ، وَزَوْجًا خَيْرًا مِنْ زَوْجِهِ، وَأَدْخِلْهُ الْجَنَّةَ، وَأَعِذْهُ مِنْ عَذَابِ الْقَبْرِ وَمِنْ عَذَابِ النَّارِ', tr: 'Allāhumma-ghfir lahu wa-rḥamh, wa ‘āfihi wa-‘fu ‘anh, wa akrim nuzulah, wa wassi‘ mudkhalah, wa-ghsilhu bi-l-mā’i wa-th-thalji wa-l-barad, wa naqqihi mina-l-khaṭāyā kamā naqqayta-th-thawba-l-abyaḍa mina-d-danas, wa abdilhu dāran khayran min dārih, wa ahlan khayran min ahlih, wa zawjan khayran min zawjih, wa adkhilhu-l-janna, wa a‘idh-hu min ‘adhābi-l-qabri wa min ‘adhābi-n-nār', fr: 'Ô Allah, pardonne-lui, fais-lui miséricorde, préserve-le et efface ses fautes ; honore son accueil et élargis sa demeure ; lave-le avec l’eau, la neige et la grêle, purifie-le des péchés comme on purifie le vêtement blanc de la souillure ; donne-lui en échange une demeure meilleure que la sienne, une famille meilleure que la sienne et un conjoint meilleur que le sien ; fais-le entrer au Paradis et protège-le du châtiment de la tombe et du châtiment du Feu.', note: 'Dans le hadith, la fin est rapportée « du châtiment de la tombe ou du châtiment du Feu » (hésitation du narrateur).', ref: 'Sahih Muslim 963' },
  { id: 'qubur', cat: 'defunts', title: 'En visitant le cimetière', when: 'En entrant au cimetière', ar: 'السَّلَامُ عَلَيْكُمْ أَهْلَ الدِّيَارِ مِنَ الْمُؤْمِنِينَ وَالْمُسْلِمِينَ، وَإِنَّا إِنْ شَاءَ اللَّهُ لَلَاحِقُونَ، أَسْأَلُ اللَّهَ لَنَا وَلَكُمُ الْعَافِيَةَ', tr: 'As-salāmu ‘alaykum ahla-d-diyāri mina-l-mu’minīna wa-l-muslimīn, wa innā in shā’a-llāhu la-lāḥiqūn, as’alu-llāha lanā wa lakumu-l-‘āfiya', fr: 'Paix sur vous, habitants de ces demeures, croyants et musulmans ; nous vous rejoindrons, si Allah le veut. Je demande à Allah la préservation pour nous et pour vous.', ref: 'Sahih Muslim 975' },

  // ── Invocations générales ───────────────────────────────────
  { id: 'hasana', cat: 'generale', title: 'Une belle part ici-bas et dans l’au-delà', when: 'À tout moment', ar: 'رَبَّنَا آتِنَا فِي الدُّنْيَا حَسَنَةً وَفِي الْآخِرَةِ حَسَنَةً وَقِنَا عَذَابَ النَّارِ', tr: 'Rabbanā ātinā fi-d-dunyā ḥasanatan wa fi-l-ākhirati ḥasanatan wa qinā ‘adhāba-n-nār', fr: 'Notre Seigneur, accorde-nous une belle part ici-bas et une belle part dans l’au-delà, et protège-nous du châtiment du Feu.', ref: 'Coran 2:201 ; Sahih al-Bukhari 6389 (l’invocation la plus fréquente du Prophète ﷺ)' },
  { id: 'huda', cat: 'generale', title: 'Guidée, piété, chasteté, suffisance', when: 'À tout moment', ar: 'اللَّهُمَّ إِنِّي أَسْأَلُكَ الْهُدَى، وَالتُّقَى، وَالْعَفَافَ، وَالْغِنَى', tr: 'Allāhumma innī as’aluka-l-hudā, wa-t-tuqā, wa-l-‘afāfa, wa-l-ghinā', fr: 'Ô Allah, je Te demande la bonne guidée, la piété, la chasteté et la suffisance.', ref: 'Sahih Muslim 2721' },
  { id: 'taqwaha', cat: 'generale', title: 'Donne à mon âme sa piété', when: 'À tout moment', ar: 'اللَّهُمَّ آتِ نَفْسِي تَقْوَاهَا، وَزَكِّهَا أَنْتَ خَيْرُ مَنْ زَكَّاهَا، أَنْتَ وَلِيُّهَا وَمَوْلَاهَا، اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنْ عِلْمٍ لَا يَنْفَعُ، وَمِنْ قَلْبٍ لَا يَخْشَعُ، وَمِنْ نَفْسٍ لَا تَشْبَعُ، وَمِنْ دَعْوَةٍ لَا يُسْتَجَابُ لَهَا', tr: 'Allāhumma āti nafsī taqwāhā, wa zakkihā anta khayru man zakkāhā, anta waliyyuhā wa mawlāhā. Allāhumma innī a‘ūdhu bika min ‘ilmin lā yanfa‘, wa min qalbin lā yakhsha‘, wa min nafsin lā tashba‘, wa min da‘watin lā yustajābu lahā', fr: 'Ô Allah, donne à mon âme sa piété et purifie-la, Tu es le meilleur à la purifier ; Tu es son Protecteur et son Maître. Ô Allah, je cherche refuge auprès de Toi contre une science qui ne profite pas, un cœur qui ne s’humilie pas, une âme jamais rassasiée et une invocation qui n’est pas exaucée.', ref: 'Sahih Muslim 2722' },
  { id: 'thabbit', cat: 'generale', title: 'Affermis mon cœur', when: 'Pour la constance dans la foi', ar: 'يَا مُقَلِّبَ الْقُلُوبِ ثَبِّتْ قَلْبِي عَلَى دِينِكَ', tr: 'Yā muqalliba-l-qulūb, thabbit qalbī ‘alā dīnik', fr: 'Ô Toi qui retournes les cœurs, affermis mon cœur sur Ta religion.', ref: 'Jami‘ at-Tirmidhi 2140' },
  { id: 'ilm', cat: 'generale', title: 'Accrois mon savoir', when: 'Avant d’étudier', ar: 'رَبِّ زِدْنِي عِلْمًا', tr: 'Rabbi zidnī ‘ilmā', fr: 'Seigneur, accrois mon savoir.', ref: 'Coran 20:114' },
  { id: 'istikhara', cat: 'generale', title: 'La prière de consultation (istikhara)', when: 'Après deux rak‘a surérogatoires, avant une décision', ar: 'اللَّهُمَّ إِنِّي أَسْتَخِيرُكَ بِعِلْمِكَ، وَأَسْتَقْدِرُكَ بِقُدْرَتِكَ، وَأَسْأَلُكَ مِنْ فَضْلِكَ الْعَظِيمِ، فَإِنَّكَ تَقْدِرُ وَلَا أَقْدِرُ، وَتَعْلَمُ وَلَا أَعْلَمُ، وَأَنْتَ عَلَّامُ الْغُيُوبِ، اللَّهُمَّ إِنْ كُنْتَ تَعْلَمُ أَنَّ هَذَا الْأَمْرَ خَيْرٌ لِي فِي دِينِي وَمَعَاشِي وَعَاقِبَةِ أَمْرِي فَاقْدُرْهُ لِي، وَإِنْ كُنْتَ تَعْلَمُ أَنَّ هَذَا الْأَمْرَ شَرٌّ لِي فِي دِينِي وَمَعَاشِي وَعَاقِبَةِ أَمْرِي فَاصْرِفْهُ عَنِّي وَاصْرِفْنِي عَنْهُ، وَاقْدُرْ لِيَ الْخَيْرَ حَيْثُ كَانَ، ثُمَّ رَضِّنِي بِهِ', tr: 'Allāhumma innī astakhīruka bi-‘ilmik, wa astaqdiruka bi-qudratik, wa as’aluka min faḍlika-l-‘aẓīm, fa-innaka taqdiru wa lā aqdir, wa ta‘lamu wa lā a‘lam, wa anta ‘allāmu-l-ghuyūb. Allāhumma in kunta ta‘lamu anna hādha-l-amra khayrun lī fī dīnī wa ma‘āshī wa ‘āqibati amrī fa-qdurhu lī, wa in kunta ta‘lamu anna hādha-l-amra sharrun lī fī dīnī wa ma‘āshī wa ‘āqibati amrī fa-ṣrifhu ‘annī wa-ṣrifnī ‘anh, wa-qdur liya-l-khayra ḥaythu kān, thumma raḍḍinī bih', fr: 'Ô Allah, je Te demande de choisir pour moi par Ta science, je Te demande la capacité par Ta puissance, et je Te demande de Ta grâce immense : Tu peux et je ne peux pas, Tu sais et je ne sais pas, et Tu connais parfaitement l’invisible. Ô Allah, si Tu sais que cette affaire (on la nomme) est un bien pour moi dans ma religion, ma vie et l’issue de mon affaire, décrète-la pour moi ; et si Tu sais qu’elle est un mal pour moi dans ma religion, ma vie et l’issue de mon affaire, écarte-la de moi et écarte-moi d’elle, décrète pour moi le bien où qu’il soit, puis rends-moi satisfait de lui.', note: 'Le narrateur rapporte aussi « ‘ājili amrī wa ājilih » (mon affaire immédiate et future) à la place de « ‘āqibati amrī ».', ref: 'Sahih al-Bukhari 1166 ; Sahih al-Bukhari 6382' },
];

export const duaCatLabel = (id: string) => DUA_CATS.find((c) => c.id === id)?.label ?? id;
